// Concept cards written from the lecture slides (2025 decks in "D7024E Lecture slides/"
// and the 2026 decks in "D7024E_Lectures_2026/").
// Fields: id, topics, q (question), a (answer; lines starting with "- " render as a list),
// src (where to read more).
window.CONCEPT_CARDS = [
  // ------------------------------------------------------------ basics
  { id: "c-basics-def", topics: ["basics"], src: "L1 Introduction",
    q: "What characterises a distributed system?",
    a: "A collection of autonomous nodes that cooperate over a network and appear to the user as a single service.\n- No common clock\n- No shared memory, so nodes interact only by message passing\n- Geographic separation (at least racks), so communication time is not negligible\n- Heterogeneity: different speeds, storage and operating systems\n- Independent (partial) failures" },
  { id: "c-basics-why", topics: ["basics"], src: "L1 Introduction",
    q: "Why build distributed systems? Name the main motivations.",
    a: "- Better performance/cost ratio and resource sharing\n- Reliability: availability, integrity, fault tolerance (seamless fail-over)\n- Access to remote data and resources\n- Scalability: nodes can be added or removed\n- Modularity and incremental expansion" },
  { id: "c-basics-decentral", topics: ["basics"], src: "L1 Introduction / L4 DHT",
    q: "Distributed vs decentralized: what is the difference?",
    a: "Distributed: the service runs on many cooperating nodes. Decentralized: additionally, nobody is in charge and all nodes are equivalent, with no special node and no single point of failure, technical or administrative. Decentralized implies distributed, not the other way round. A cloud service is distributed but centrally run. Kademlia is decentralized." },
  { id: "c-basics-scal", topics: ["basics"], src: "L1 Introduction",
    q: "Horizontal vs vertical scalability, and what is linear horizontal scalability?",
    a: "Vertical: a bigger machine (more CPU, RAM). Horizontal: more machines. Linear horizontal scalability means total throughput grows in proportion to the number of nodes. Shared state, global consensus or central bottlenecks prevent it." },
  { id: "c-basics-transp", topics: ["basics"], src: "L1 Introduction",
    q: "List the transparencies a distributed system can provide.",
    a: "- Access: local and remote resources used with identical operations\n- Location: no need to know where a resource is\n- Concurrency: shared resources used without interference\n- Replication: replicas invisible to users\n- Failure: faults concealed\n- Mobility: resources and clients can move\n- Performance: reconfigure as load varies\n- Scaling: grow without changing structure or algorithms" },
  { id: "c-basics-coffman", topics: ["basics", "databases"], src: "L1 Introduction",
    q: "What are the four Coffman conditions for deadlock?",
    a: "- Mutual exclusion: a resource can be held by only one at a time\n- Hold and wait: holding a resource while waiting for another\n- No preemption: resources cannot be forcibly taken away\n- Circular wait: P1 waits for P2, which waits for ... Pn, which waits for P1\nAll four must hold. Break one to prevent deadlock." },
  { id: "c-basics-models", topics: ["basics", "communication"], src: "L3 Communication (2026)",
    q: "Which three system-model choices must you make before reasoning about a distributed algorithm?",
    a: "- Network: reliable links, fair-loss links (lost, duplicated or reordered, but retries eventually succeed), or arbitrary links (adversary)\n- Node failures: crash-stop, crash-recovery, omission, or Byzantine (arbitrary)\n- Timing: synchronous (known bounds), partially synchronous (eventually bounded), or asynchronous (no bounds)\nIf the assumptions are wrong, all guarantees are off." },
  { id: "c-basics-syncasync", topics: ["basics", "communication"], src: "L1 Introduction",
    q: "Synchronous vs asynchronous distributed systems (interaction model)?",
    a: "Synchronous: known bounds on execution time, message delay and clock drift. Common inside embedded systems. Asynchronous: arbitrary execution speed, unbounded message delay and arbitrary drift. This is the realistic model for Internet and web systems. In an asynchronous system a slow node cannot be told apart from a crashed one." },
  { id: "c-basics-immutable", topics: ["basics"], src: "L2 Kademlia & actors / L7 Data sync",
    q: "Why are immutability and idempotence so valuable in distributed systems?",
    a: "Immutable data cannot conflict, so copies, caches and replicas are always valid and data races are impossible (the root cause of races is shared mutable memory). Idempotent operations can be retried or delivered twice without harm, which matters because every retry protocol creates duplicates. Both make decentralized design easier." },

  // ------------------------------------------------------------ communication
  { id: "c-comm-marshal", topics: ["communication"], src: "L3 Communication",
    q: "What is marshalling, and why is it needed?",
    a: "Converting in-memory data or objects into a compact, platform-independent byte format for transfer. Unmarshalling reverses it. It is needed because sender and receiver may differ in language, byte order and memory layout. Examples: Protobuf (schemas, binary, backward/forward compatible), Cap'n Proto, JSON. Marshalling is reversible, unlike hashing." },
  { id: "c-comm-rpc", topics: ["communication"], src: "L3 Communication",
    q: "How does an RPC work, and what are its challenges?",
    a: "1. Client calls a local stub\n2. Stub marshals the arguments\n3. Request is sent over the network\n4-5. Server stub receives and unmarshals\n6. Real function runs\n7-8. Result is marshalled back and returned as if local.\nChallenges: latency, partial failures (did the call execute?), version compatibility. Examples: gRPC, Java RMI, JSON-RPC, CORBA. In the lab: PING, STORE, FIND_NODE, FIND_VALUE." },
  { id: "c-comm-primitives", topics: ["communication"], src: "L1 Introduction",
    q: "Synchronous vs asynchronous send primitives?",
    a: "Synchronous: send completes only when the matching receive has completed (handshake, rendezvous). It blocks the sender and is easy to reason about, since send and receive form one atomic event. Asynchronous: non-blocking, so control returns once data is copied out of the user buffer, and a handle can be checked later. Much better performance when round-trip times are significant, as in geo-distributed systems." },
  { id: "c-comm-indirect", topics: ["communication", "pubsub"], src: "L3 Communication",
    q: "Direct vs indirect communication? What are space and time decoupling?",
    a: "Direct: sender talks straight to the receiver (RPC, request/reply). Simple and synchronous, suits tightly coupled systems. Indirect: through an intermediary (group communication, pub-sub, queues, tuple spaces).\n- Space decoupling: the sender does not know who the receivers are\n- Time decoupling: sender and receiver need not exist at the same time" },
  { id: "c-comm-broadcast", topics: ["communication", "pubsub"], src: "L3 Communication",
    q: "Define FIFO, causal and total order broadcast.",
    a: "- FIFO: messages from the same sender are delivered in the order sent\n- Causal: if broadcast(m1) happens-before broadcast(m2), m1 is delivered before m2 everywhere\n- Total order: all nodes deliver all messages in the same order\n- FIFO-total order: both\nBest-effort broadcast may drop messages. Reliable broadcast retransmits so all non-faulty nodes deliver every message." },
  { id: "c-comm-gossip", topics: ["communication", "pubsub"], src: "L3 Communication",
    q: "How does a gossip (epidemic) protocol work and what are its properties?",
    a: "Each node periodically sends what it knows to a few random peers, and they merge it. Information spreads like an epidemic and reaches all nodes in O(log N) rounds.\n- No central coordinator\n- Scales to large, dynamic networks\n- Resilient to node failures\n- Probabilistic, eventually consistent dissemination (membership, failure detection, anti-entropy)" },
  { id: "c-comm-actor", topics: ["communication", "dht"], src: "L2 Kademlia & actors",
    q: "What is the actor model and why does it help with concurrency in the lab?",
    a: "An actor has private state, a FIFO mailbox and an ID. Actors interact only by asynchronously sending immutable messages, so there is no shared memory. Messages are handled one at a time, which serialises access to the state without locks. Example: a routing-table actor handling add/closest requests. In Go: one goroutine owning the state, fed by a channel. It avoids data races and the deadlocks that come with fine-grained mutexes." },
  { id: "c-comm-granularity", topics: ["communication", "basics"], src: "L1 Introduction",
    q: "What is program granularity, and which kind suits distributed systems?",
    a: "The ratio of computation to communication. Coarse-grained work (large independent blocks between communication) suits loosely coupled systems like distributed MIMD systems, where network round trips are expensive. Fine-grained work suits tightly coupled systems (SIMD, embedded)." },

  // ------------------------------------------------------------ networking
  { id: "c-net-nat", topics: ["networking"], src: "Old lectures (P2P / NAT traversal)",
    q: "STUN vs TURN vs ICE: how do peers behind NAT connect?",
    a: "- STUN: the node behind the NAT asks a public STUN server which public IP:port it appears as, shares that with the peer, then both try to punch holes for a direct connection. Does not work with symmetric NAT.\n- TURN: both peers connect outward to a public relay, which forwards all payload. Always works, but costs latency and bandwidth.\n- ICE: tries candidates in order (local, STUN-reflexive, TURN-relayed) and uses the best that works." },
  { id: "c-net-dns", topics: ["networking"], src: "L1 Introduction",
    q: "How can DNS be used for load balancing and fail-over? What are the limits?",
    a: "- Round-robin DNS: the reply lists several IPs, rotated per query. Coarse and load-insensitive. The client can fail over to the next address (slow, around 30 s, client-controlled).\n- Health-checked DNS hosting: the provider heartbeats the registered servers and advertises only live ones with a short TTL, so fail-over is controlled by the DNS side.\nLimit: TTL and caching. A short TTL loads DNS, a long TTL reacts slowly. Session state on a failed server is lost." },
  { id: "c-net-dispatcher", topics: ["networking", "microservices"], src: "L1 Introduction",
    q: "What is dispatcher-based load balancing for a web cluster?",
    a: "A front device with one virtual IP receives all requests and spreads them over servers by packet rewriting (single or double), packet forwarding or HTTP redirection. It is transparent to clients and DNS. The dispatcher must be made redundant, and geographic fail-over needs a combination with DNS. Front-end servers are kept stateless, with persistent state in replicated back-end databases." },
  { id: "c-net-adhoc", topics: ["networking"], src: "Old lectures (mobile ad hoc)",
    q: "Proactive vs reactive routing in mobile ad-hoc networks?",
    a: "Proactive (table-driven, e.g. OLSR, DSDV): routes to all destinations are maintained continuously, so a path is known before sending. Costs control traffic even when idle. Reactive (on-demand, e.g. AODV, DSR): a route is discovered when a packet needs it. Less overhead, but a delay before the first packet." },

  // ------------------------------------------------------------ databases
  { id: "c-db-acid", topics: ["databases"], src: "Old lectures / L7 Consensus",
    q: "What does ACID mean, and what does the local transaction log contribute?",
    a: "- Atomicity: all or nothing\n- Consistency: invariants preserved\n- Isolation: concurrent transactions behave as if run in some serial order (not literally one at a time)\n- Durability: committed data survives crashes\nThe write-ahead log is flushed before commit. It allows redo after losing the RAM cache, undo of aborted transactions, and client-defined multi-statement transactions." },
  { id: "c-db-deadlock", topics: ["databases"], src: "Old exams",
    q: "How do databases deal with deadlocks?",
    a: "Lock-based concurrency control can deadlock when transactions lock items in different orders. The DBMS either detects cycles in the wait-for graph or uses timeouts, then aborts a victim and rolls it back (using the log). The client retries. Consistent lock ordering avoids many deadlocks. Resolution costs performance." },
  { id: "c-db-nosql", topics: ["databases", "consistency"], src: "Old exams",
    q: "What do NoSQL stores typically trade away compared to relational databases?",
    a: "They typically give up client-defined multi-key ACID transactions and joins. In return they get single-key or single-document atomic, lock-free operations, automatic sharding and replication, high availability and eventual (BASE) consistency. Denormalised documents or wide rows also give better data locality." },
  { id: "c-db-serial", topics: ["databases"], src: "2025 exam",
    q: "Why do atomic individual writes not make transactions serializable?",
    a: "Transactions are multi-step (read, compute, write). Two transactions can interleave between steps, for example both read x = 5 and both write 6, which loses an update. Write skew is another case. Serializability requires concurrency control: two-phase locking, MVCC with serializable snapshot isolation, or optimistic validation." },

  // ------------------------------------------------------------ consistency
  { id: "c-cap", topics: ["consistency"], src: "L5/L7 Data sync",
    q: "State the CAP theorem and sketch the proof.",
    a: "During a network partition (P), a replicated system must choose between consistency (C, linearizability: every read sees the latest completed write) and availability (A, every request to a non-failing node gets a response).\nProof: a write reaches node A, A cannot reach B, and a read arrives at B. B either answers with stale data (violates C) or refuses or waits (violates A).\nThe choice only bites during partitions, and you can decide per operation." },
  { id: "c-cap-examples", topics: ["consistency"], src: "L5 Data sync",
    q: "Give examples of CP, AP and 'CA' systems.",
    a: "- CP: etcd, ZooKeeper, MongoDB (wait for consistency, may be unavailable). Use for banking and bookings.\n- AP: Kademlia, offline-first apps, Dynamo-style stores (always answer, may be stale).\n- CA: only a single-node system such as one PostgreSQL instance, since the only way to avoid partitions is not to distribute." },
  { id: "c-cons-spectrum", topics: ["consistency"], src: "L5/L7 Data sync",
    q: "Order the consistency models from strongest to weakest.",
    a: "Linearizability > sequential > causal > session > eventual > weak/best-effort.\nStronger models are slower, have higher latency and scale less. Weaker models are fast, low-latency and scalable, but the application must handle anomalies." },
  { id: "c-cons-lin", topics: ["consistency"], src: "L7 Data sync (2026)",
    q: "What is linearizability, and when do you need it?",
    a: "The system behaves as if there were a single copy and each operation took effect at one instant inside its call interval, in real-time order. Once an operation completes, every later operation sees it. You need it whenever a decision is taken from a read: bookings, balances, 'is this name taken?', leader election. Implemented with consensus or a leader plus synchronous replication. Not available under partition." },
  { id: "c-cons-seq", topics: ["consistency"], src: "L7 Data sync (2026)",
    q: "What is sequential consistency? Give examples.",
    a: "All operations appear in one total order that respects each client's program order, but not necessarily real time. Everyone hears the same story, not at the same time. A stale read is allowed, a different order per client is not. Examples: Kafka within a partition (totally ordered log), blockchains (all nodes eventually see block 1, 2, 3, 4)." },
  { id: "c-cons-causal", topics: ["consistency", "clocks"], src: "L7 Data sync (2026)",
    q: "What is causal consistency and how is it implemented?",
    a: "Writes related by happens-before are seen in that order by everyone. Concurrent writes may be seen in different orders. Example: a reply must never be visible before the post it answers. It is the strongest model that stays available under partition with local reads and writes. Implementation: tag writes with vector clocks and buffer a write until all its dependencies have been applied (V[j] = local[j]+1 and V[k] <= local[k] for all other k)." },
  { id: "c-cons-session", topics: ["consistency"], src: "L5 Data sync",
    q: "What are the four session guarantees?",
    a: "- Read your writes: you see your own updates\n- Monotonic reads: you never go back to an older state\n- Monotonic writes: your writes are applied in order\n- Writes follow reads: your writes are ordered after what you read\nThey hold within one session, not across users." },
  { id: "c-cons-eventual", topics: ["consistency", "dht"], src: "L5/L7 Data sync",
    q: "What does eventual consistency promise, and how does Kademlia achieve it?",
    a: "If updates stop and messages get through, all replicas eventually converge. Nothing is promised about when, or about order: before convergence a read may return any value. It is a liveness property. Kademlia stores on the k closest nodes without waiting for all, the publisher republishes hourly, nodes re-replicate to any of the k closest that lack the value, and values expire after 24 h without refresh." },
  { id: "c-cons-shard", topics: ["consistency", "basics"], src: "L5/L7 Data sync",
    q: "Sharding vs replication vs caching vs erasure coding?",
    a: "- Sharding (partitioning): each node holds a different part. Scales storage and throughput.\n- Replication: each node holds the same data. Gives availability, fault tolerance and local reads.\n- Caching: temporary copies near clients for speed.\n- Erasure coding: k data and m parity fragments, any k rebuild everything. Uses less storage than replication (RS(4,2) is 1.5×) but makes reads and repairs costly. Good for large, cold, immutable objects." },
  { id: "c-cons-leaders", topics: ["consistency"], src: "L7 Data sync (2026)",
    q: "Single leader vs multi-leader vs leaderless replication?",
    a: "- Single leader: one node orders all writes and followers replay them. Simple, but the leader is a bottleneck and a fail-over risk.\n- Multi-leader: several sites (regions, offline devices) accept writes. Concurrent writes are unavoidable, so a conflict policy is mandatory.\n- Leaderless (quorum): the client writes to and reads from several replicas and waits for a quorum. With R + W > N, read and write sets overlap.\nTopology, acknowledgement rule and conflict policy are separate choices." },
  { id: "c-cons-write3", topics: ["consistency"], src: "L7 Data sync (2026)",
    q: "'Write' can mean three different things. Which?",
    a: "1. Saved on this device: durable local storage, survives an app crash.\n2. Acknowledged by the service: durably stored server-side, survives losing the phone.\n3. Visible to others: other replicas have applied it.\nUntil step 3, others may still see the old state." },
  { id: "c-cons-store-acks", topics: ["consistency", "dht"], src: "L7 Data sync (2026)",
    q: "In the Kademlia lab, how many acknowledgements should STORE wait for (k = 3, churn)?",
    a: "- 1 ack: fast, but that copy may be the only one\n- Majority (2 of 3): durable enough and still available; overlaps a majority read\n- All k: strongest, but one slow or dead node blocks the write\nA majority is the usual compromise." },
  { id: "c-cons-idem", topics: ["consistency", "communication"], src: "L7 Data sync (2026)",
    q: "Why must operations be idempotent when you retry, and how do you make them so?",
    a: "A lost ack leads to a retry, which duplicates the request. 'count += 1' applied twice gives the wrong answer. 'set done = true' applied twice is still correct. To make any operation idempotent, give it a unique ID and record applied IDs in the same transaction, so a repeated ID returns the stored result. Either the operation is naturally idempotent or you add an ID and a dedup record, never neither." },
  { id: "c-cons-2pc", topics: ["consistency", "consensus", "databases"], src: "L5/L7 Data sync, L7 Consensus",
    q: "How does two-phase commit work, and what is its weakness?",
    a: "Phase 1 (prepare/vote): the coordinator asks all participants whether they can commit, and they vote yes or no (they cannot propose alternatives). Phase 2 (commit/abort): if all voted yes, the coordinator tells everyone to commit, otherwise to abort.\nIt gives atomicity across replicas or shards. Weakness: it blocks if the coordinator crashes after prepare, because participants hold locks and cannot decide alone. 3PC, Paxos and Raft address this." },
  { id: "c-cons-tomb", topics: ["consistency"], src: "L7 Data sync (2026)",
    q: "Why is delete hard in a replicated system, and what are tombstones?",
    a: "A deletion removes the evidence of itself: 'I deleted X' and 'I never had X' look the same. When an offline replica that still holds X syncs, X is copied back (resurrection). Delete vs concurrent edit is also ambiguous, and stale reads can show deleted data.\nFix: keep a tombstone ('deleted X at version v') that wins over older copies. Garbage-collect tombstones only after every replica has seen them, or force replicas older than the retention window to resync fully." },
  { id: "c-cons-merkle", topics: ["consistency"], src: "L7 Data sync (2026)",
    q: "How do Merkle trees help replicas find what differs (anti-entropy)?",
    a: "Each replica hashes its keys into a tree of hashes. Compare root hashes: if they differ, descend only into children whose hashes differ and skip matching subtrees, then fetch only the differing leaves. This needs O(log n) round trips instead of sending everything (used in Dynamo and Cassandra). Leaves should hash (key, version, deletion marker, value), otherwise replicas can agree on the value but disagree on whether it was deleted." },
  { id: "c-cons-antientropy", topics: ["consistency", "communication"], src: "L7 Data sync (2026)",
    q: "What is anti-entropy?",
    a: "A background process (Demers et al. 1987) in which each replica periodically picks a random peer and compares state, using version vectors or a Merkle root, then exchanges what is missing (push-pull). Merges are idempotent, so repeated exchanges are harmless. Because of epidemic spread, everyone has everything after O(log n) rounds. It also recovers updates whose first transmission was lost." },
  { id: "c-cons-logship", topics: ["consistency", "consensus"], src: "L7 Data sync (2026)",
    q: "How does log shipping let followers catch up, and when is a snapshot needed?",
    a: "Followers replay the leader's ordered log from their last position (Raft prevLogIndex/prevLogTerm, PostgreSQL WAL, Kafka offsets). Gaps are detected, never skipped. If the follower was offline longer than the log retention, it installs a snapshot and replays the tail. Retention time and the supported offline period are one decision. With several leaders you need one position per leader, i.e. a version vector." },

  // ------------------------------------------------------------ clocks
  { id: "c-clk-physical", topics: ["clocks"], src: "L3 Communication (2026)",
    q: "Why can't physical timestamps order events across nodes?",
    a: "Clocks drift (quartz is around 50 ppm, 1 ppm is about 86 ms/day, and drift depends on temperature), and synchronisation has an error bound. A message can carry timestamp t2 < t1 even though it was caused by an earlier message. Physical time is fine for timeouts and logs, but logical clocks are needed to capture causality." },
  { id: "c-clk-hb", topics: ["clocks"], src: "L3 Communication / L5 Data sync",
    q: "Define the happens-before relation (a -> b).",
    a: "a -> b if:\n- a and b are on the same node and a comes first in its local order, or\n- a is the sending of message m and b is the receipt of m, or\n- there is a c with a -> c and c -> b (transitivity).\nIt is a partial order. If neither a -> b nor b -> a, they are concurrent (a || b). a -> b means a might have caused b; a || b means it cannot have." },
  { id: "c-clk-lamport", topics: ["clocks"], src: "L3 Communication / L5 Data sync",
    q: "Lamport clock: rules and guarantee.",
    a: "Each node has a counter t.\n- Local event: t += 1\n- Send: t += 1 and attach t\n- Receive t': t = max(t, t') + 1\nGuarantee: a -> b implies L(a) < L(b). The converse does not hold, so Lamport clocks cannot detect concurrency. Ordering by (L(e), node id) gives a total order that is consistent with causality." },
  { id: "c-clk-vector", topics: ["clocks"], src: "L3 Communication / L5 Data sync",
    q: "Vector clock: rules and how to compare two vectors.",
    a: "Node i keeps a vector T of n counters.\n- Local event or send: T[i] += 1, and send the whole T\n- Receive T': T[j] = max(T[j], T'[j]) for all j, then T[i] += 1\nCompare: A -> B if A[k] <= B[k] for all k and A[k] < B[k] for some k. If each is ahead in some position, A || B (concurrent).\nA vector timestamp represents the event plus all of its causal history. Use (vector, id) as a tie-breaker for a total order." },
  { id: "c-clk-cut", topics: ["clocks"], src: "L1 Introduction",
    q: "What is a consistent cut (global state)?",
    a: "A snapshot of every process's state, plus messages in flight in the channels, such that if a receive event is in the cut, its send is too. An inconsistent cut records a message received that was never sent." },

  // ------------------------------------------------------------ crdt / collaborative editing
  { id: "c-crdt-def", topics: ["crdt"], src: "L5/L7 Data sync",
    q: "What is a CRDT and what does it guarantee?",
    a: "A Conflict-free Replicated Data Type. Replicas update locally without coordination and merge with a defined function. Replicas that have seen the same updates hold the same state regardless of order (strong eventual consistency). No locks, consensus or central server are needed, and delays or failures cannot break convergence. Convergence still requires the updates to be delivered eventually. Used in Automerge, Yjs, Riak, Redis, Apple Notes and Figma." },
  { id: "c-crdt-laws", topics: ["crdt"], src: "L5/L7 Data sync",
    q: "Which three merge laws make a CRDT converge, and which delivery fault does each make harmless?",
    a: "The merge must be the join (least upper bound) of a join-semilattice:\n- Commutative, a + b = b + a: messages arriving in a different order\n- Associative, (a + b) + c = a + (b + c): messages batched or split differently\n- Idempotent, a + a = a: a message delivered twice" },
  { id: "c-crdt-types", topics: ["crdt"], src: "L5 Data sync",
    q: "State-based vs operation-based CRDTs, with examples.",
    a: "State-based (CvRDT): send the whole state and merge with the join. Tolerates loss and duplication. Operation-based (CmRDT): send only operations. Smaller, but needs reliable (often causal) delivery.\nExamples: G-Counter (one counter per replica, merge = element-wise max, value = sum), PN-Counter (two G-Counters), G-Set, LWW register, OR-set, sequence CRDTs (RGA, LSEQ)." },
  { id: "c-crdt-lww", topics: ["crdt", "clocks"], src: "L7 Data sync (2026)",
    q: "LWW register vs multi-value register?",
    a: "LWW (last-writer-wins): order writes by (vector or Lamport clock, replica-id tie-break) and keep the highest. Deterministic and simple, but a concurrent write is silently lost. 'Last' means last in the chosen order, not by wall clock. Multi-value register: keep all concurrent values and show the conflict. A later write that has seen both replaces them. Nothing is lost, but the UI must handle conflicts." },
  { id: "c-crdt-ot", topics: ["crdt"], src: "L6 Realtime collaboration",
    q: "How does Operational Transformation (OT) work?",
    a: "Edits are applied locally at once. Incoming concurrent operations are transformed against local ones so their positions still match the user's intention. Example: Alice deletes A at index 0 while Bob inserts X at index 1; Bob's insert is shifted to index 0 on Alice's side, and both converge to XBCD. Jupiter OT (Xerox PARC) uses a 2D state space of (client ops, server ops) and needs a central server to order and transform. Used in early Google Docs and Etherpad." },
  { id: "c-crdt-seq", topics: ["crdt"], src: "L6 Realtime collaboration",
    q: "How do sequence CRDTs (Logoot/LSEQ, RGA) avoid shifting indices?",
    a: "- LSEQ/Logoot: each character gets a unique, immutable position identifier, a path in a tree such as (4,1,2), allocated between its neighbours. A new tree level is created when there is no room. Sorting by identifier gives the document.\n- RGA: each character references the element it was inserted after, with ID tie-breaks. Deletes become tombstones.\nNo transformation is needed and no other IDs change." },
  { id: "c-crdt-interleave", topics: ["crdt"], src: "L6/L7",
    q: "What is the interleaving problem?",
    a: "Two users typing concurrently into the same gap get identifiers allocated independently in the same range. After merge (set union, sorted) the characters interleave: 'students' and 'friends' become 'Hi sftruideenndtss !'. Replicas converge, but intent is lost. Present in Logoot and LSEQ, reduced in RGA and Yjs, and minimised by Fugue (2023). OT can interleave too. Mitigations: batch keystrokes into words, show live cursors." },
  { id: "c-crdt-vs-ot", topics: ["crdt"], src: "L6 Realtime collaboration",
    q: "OT vs CRDT: pros and cons.",
    a: "OT pros: strong intention preservation, compact operations, proven (Google Docs). Cons: needs a central server, complex transformation functions, the server is a bottleneck, offline is hard.\nCRDT pros: decentralised and peer-to-peer, offline-friendly, correctness follows from the maths. Cons: weaker intention preservation (interleaving), metadata overhead per character, tombstone accumulation." },
  { id: "c-crdt-principles", topics: ["crdt"], src: "L6 Realtime collaboration",
    q: "What are the principles of collaborative (and offline-first) editing?",
    a: "1. Apply changes locally at once (optimistic updates). Locking each keystroke against a server (50-400 ms) feels broken.\n2. Sync with others in the background.\n3. Resolve conflicts automatically.\n4. Preserve user intent." },

  // ------------------------------------------------------------ consensus (Raft, Paxos, ZooKeeper)
  { id: "c-cons-safelive", topics: ["consensus"], src: "L7 Consensus / L8 BFT",
    q: "Define safety and liveness for consensus. Can both be guaranteed?",
    a: "Safety: nothing bad happens. Every correct node decides the same value, and only a proposed value is chosen. Liveness: something good eventually happens. Every correct node eventually decides.\nSafety can be guaranteed. Liveness cannot in a fully asynchronous network (FLP), so practical protocols are always safe and live only when the network is stable long enough. They are independent properties." },
  { id: "c-cons-flp", topics: ["consensus", "bft"], src: "L8 BFT",
    q: "What does the FLP impossibility result say?",
    a: "In a fully asynchronous network, no deterministic protocol can guarantee liveness (termination) if even one node may crash. You cannot tell a crashed node from a slow one. Practical protocols therefore assume partial synchrony: safety never depends on timing, and liveness relies on an eventual (unknown) bound on delays." },
  { id: "c-cons-paxos", topics: ["consensus"], src: "L7 Consensus",
    q: "Outline Paxos.",
    a: "Roles: proposer, acceptor, learner (a node usually has several). Rounds have unique, increasing numbers.\n- 1a Prepare(n): may I propose with number n?\n- 1b Promise: the acceptor will not accept anything below n and reports its highest accepted (n', v')\n- 2a Accept(n, v) once a majority has promised (v must be the highest previously accepted value, if any)\n- 2b Accepted, sent to the learners. A majority means chosen.\nN >= 2F+1 and at least 4(N-1) messages per round. Always safe, not guaranteed live (dueling proposers, mitigated with randomised timers)." },
  { id: "c-raft-overview", topics: ["consensus"], src: "L7 Consensus",
    q: "What is Raft and what are its three sub-problems?",
    a: "A non-Byzantine consensus algorithm designed for understandability. It maintains a replicated, globally consistent command log, so every server runs the same commands in the same order (a replicated state machine).\n1. Leader election\n2. Log replication: clients talk to the leader, which replicates and overwrites inconsistencies\n3. Safety: only a server with an up-to-date log can become leader\nIt makes progress while a majority is up (n = 2f+1). Used by etcd (Kubernetes), Consul and Kafka KRaft." },
  { id: "c-raft-election", topics: ["consensus"], src: "L7 Consensus",
    q: "How does Raft leader election work?",
    a: "Servers start as followers. The leader sends heartbeats (empty AppendEntries). A follower that hears nothing within its election timeout (randomised, e.g. 150-300 ms) becomes a candidate: it increments the term, votes for itself and sends RequestVote. A majority of votes makes it leader for that term. On a split vote, everyone waits a new random timeout and retries. Seeing a higher term makes a node step down to follower." },
  { id: "c-raft-term", topics: ["consensus"], src: "L7 Consensus",
    q: "What is a term in Raft?",
    a: "A logical epoch numbered by a monotonically increasing integer. Each term starts with an election and has at most one leader. It may have none after a split vote. Terms act as a logical clock: messages with an older term are rejected, and stale leaders step down. Different servers may notice term changes at different times." },
  { id: "c-raft-log", topics: ["consensus"], src: "L7 Consensus",
    q: "How does Raft log replication and commit work?",
    a: "The leader appends the client command to its log and sends AppendEntries to all followers in parallel, retrying slow ones (RPCs are idempotent). Once the entry is stored on a majority it is committed: the leader applies it to its state machine and replies. Followers learn the commit index from the next AppendEntries or heartbeat and apply it. Committing an entry commits all earlier ones, and entries are never skipped." },
  { id: "c-raft-safety", topics: ["consensus"], src: "L7 Consensus",
    q: "Raft safety: log matching, the election restriction, and committing old-term entries.",
    a: "- Log matching: if two logs have an entry with the same index and term, they hold the same command and identical prefixes. AppendEntries carries prevLogIndex/prevLogTerm and a follower rejects on mismatch.\n- Election restriction: a voter only grants its vote if the candidate's log is at least as up to date (last term, then length). Any two majorities intersect, so the new leader has every committed entry.\n- A leader only commits entries from its own term by counting replicas. Older entries are committed indirectly." },
  { id: "c-zk", topics: ["consensus"], src: "L7 Consensus",
    q: "What is ZooKeeper and how does it work?",
    a: "A replicated coordination service for configuration, naming, group membership, leader election and locks. Data is a hierarchical namespace of znodes, each read and written atomically in full.\n- Every server keeps a copy in memory. Clients read from the server they are connected to, while writes go via the leader and are acknowledged once a majority has persisted them.\n- Zab (primary-order atomic broadcast with epochs) gives reliable delivery, total order and the prefix property.\n- Read throughput and fault tolerance scale with servers. Write throughput does not." },
  { id: "c-zk-znodes", topics: ["consensus"], src: "L7 Consensus",
    q: "ZooKeeper znode types and watches: what are the pitfalls?",
    a: "- Persistent: lives until deleted\n- Ephemeral: removed when the creating session dies, which makes it ideal for liveness and membership\n- Sequential: a counter is appended, useful for locks and queues\nWatches are one-time triggers: they must be re-set, and changes in between can be missed. Many watches on one znode cause a herd effect (bursts of traffic). Use long enough session timeouts (GC pauses) and a dedicated disk for the transaction log." },
  { id: "c-raft-vs", topics: ["consensus"], src: "L7 Consensus",
    q: "Compare Paxos, Zab/ZooKeeper and Raft.",
    a: "- Paxos: a leader per round with all phases each time. Handles loss and reordering at once, but needs many messages and is hard to implement.\n- Zab: the three phases are used only to elect a persistent leader for an epoch, then TCP FIFO broadcast. It replicates a znode data tree.\n- Raft: a stable leader per term with randomised timers, a replicated log of immutable entries and a simple data model, designed for understandability with a detailed specification.\nAll three are non-Byzantine with n = 2f+1." },
  { id: "c-cons-scale", topics: ["consensus"], src: "L7 Consensus",
    q: "Why doesn't adding nodes to a consensus cluster improve write throughput? What should be stored there?",
    a: "Every write goes through the single leader and must be acknowledged by a majority, so more nodes means more messages per write. Clusters stay small (3, 5 or 7) and in one region. Store small, slowly changing metadata there: configuration, membership, leader identity, locks, shard maps. Bulk data belongs in sharded stores. Massive stores like Kademlia avoid global consensus entirely." },
  { id: "c-cons-election-alg", topics: ["consensus"], src: "L7 Consensus",
    q: "Name two classic leader election algorithms other than Raft.",
    a: "- Bully: on suspecting the leader is dead, a node messages all nodes with higher IDs. If none answers, it becomes leader. The highest live ID wins.\n- Ring: an election message travels around a logical ring collecting IDs (or carrying a token), and the highest ID becomes leader." },
  { id: "c-cons-equiv", topics: ["consensus", "bft"], src: "L8 BFT",
    q: "Which problems are equivalent to consensus?",
    a: "(Byzantine) consensus on a specific value, agreement on some value, atomic broadcast (all-or-nothing delivery in total order), state machine replication, and log replication. Consensus can implement linearizability." },

  // ------------------------------------------------------------ bft
  { id: "c-bft-fault", topics: ["bft"], src: "L8 BFT",
    q: "Crash fault vs Byzantine fault, and why is 'Byzantine = malicious' misleading?",
    a: "Crash fault: a node works correctly or not at all. Byzantine fault: a node may do anything, such as crash, delay, send duplicates, lie or equivocate. Byzantine is a superset of crash. A crashed node is faulty (Byzantine) no matter how honest it is. What matters is what a node can do, not why. The model can reason about malice, but faulty does not mean malicious." },
  { id: "c-bft-generals", topics: ["bft"], src: "L7 Consensus",
    q: "The Byzantine generals problem: conditions and the classic bound.",
    a: "Loyal generals must all decide the same plan, and a few traitors must not make them adopt a bad plan. With pairwise (oral) messages, consensus is impossible when there are fewer than 3m+1 generals for m traitors, i.e. with a third or more traitors. This assumes all messages arrive and everyone knows the participants. Signed messages help, since forged messages are detectable, but the protocol must still handle lost messages and leader changes." },
  { id: "c-bft-why-half", topics: ["bft"], src: "L8 BFT",
    q: "Why can't a Raft-style > n/2 majority tolerate even one Byzantine node?",
    a: "- An equivocating leader proposes A to some correct nodes and B to others. Byzantine plus a few correct votes reach a majority for both, so safety is broken.\n- A Byzantine node that can talk to both halves of a partition votes in both, giving two majorities.\nUnanimity would block on silent Byzantine nodes (no liveness). In an asynchronous network no threshold works for f < n/2." },
  { id: "c-bft-bounds", topics: ["bft", "consensus"], src: "L8 BFT",
    q: "Fault-tolerance bounds: CFT vs BFT (async/partial sync vs sync).",
    a: "- CFT (crash only): f < n/2, n >= 2f+1, quorum > n/2\n- BFT, partially synchronous: f < n/3, n >= 3f+1, quorum > 2n/3\n- BFT, synchronous with signatures: f < n/2, quorum > n/2, because a non-responsive node must have crashed, which rules out partitions\nMost popular protocols assume partial synchrony and are in the f < n/3 class." },
  { id: "c-bft-quorum", topics: ["bft"], src: "L8 BFT",
    q: "Why does a 2f+1 quorum out of n = 3f+1 guarantee BFT safety?",
    a: "Correct nodes vote at most once, Byzantine nodes may vote twice, as if there were n' = 4f+1 votes. Two conflicting quorums need 2(2f+1) = 4f+2 > 4f+1 votes, which is impossible. Equivalently, any two quorums of 2f+1 overlap in at least f+1 nodes, so at least one correct node is in both and will not vote twice." },
  { id: "c-pbft", topics: ["bft"], src: "L8 BFT",
    q: "How does PBFT work?",
    a: "Practical Byzantine Fault Tolerance (Castro & Liskov). Assumes partial synchrony, tolerates f < n/3 and needs > 2n/3 votes.\n- Views are like Raft terms. Each view has a primary chosen deterministically (round robin, no voting).\n- Three phases: pre-prepare (primary proposes), prepare (backups broadcast votes, lock), commit (decide).\n- View change when the primary fails.\nOptimistically responsive (O(message delay)) but Θ(n²) messages because of all-to-all votes." },
  { id: "c-bft-modern", topics: ["bft"], src: "L8 BFT",
    q: "How do Tendermint, HotStuff and HotStuff-2 improve on PBFT?",
    a: "- Signature aggregation: a leader collects votes into one aggregate, giving O(n) messages\n- Tendermint: load balance and linear view change, but loses optimistic responsiveness (waits Δ, the max delay)\n- HotStuff: regains responsiveness and easy pipelining, at the cost of an extra (4th) round\n- HotStuff-2: back to 3 rounds with all the properties, but degrades faster as Byzantine nodes increase\nGoals: O(δ) latency, O(n) optimistic and O(n²) worst-case communication, load balance." },

  // ------------------------------------------------------------ blockchain
  { id: "c-bc-ledger", topics: ["blockchain"], src: "L8 BFT & Blockchain",
    q: "What problem does a blockchain solve for electronic currency?",
    a: "Validation without a trusted bank:\n- Forged transactions are prevented with digital signatures\n- Replay attacks are prevented with signatures plus a nonce\n- Double spending is prevented by recording all transactions on an immutable, append-only ledger that everyone agrees on (consensus)\nOnce everyone agrees on what has happened, validation is easy. A blockchain is a distributed, decentralised, immutable ledger." },
  { id: "c-bc-utxo", topics: ["blockchain"], src: "L8 BFT & Blockchain",
    q: "What is the UTXO model in Bitcoin?",
    a: "A transaction (ID = its hash) spends unspent transaction outputs (UTXOs) as inputs and creates new outputs (amount, receiver). A UTXO works like a coin with a serial number: it is spent once and whole. Change goes back as an output to yourself, and the input-output difference is the miner fee. New coins come from the coinbase transaction in each block. Ethereum instead uses an account/balance model." },
  { id: "c-bc-block", topics: ["blockchain"], src: "L8 BFT & Blockchain",
    q: "What is in a Bitcoin block, and how does mining (proof of work) work?",
    a: "Header: hash of the previous block header, Merkle root of the transactions, nonce. Body: coinbase transaction plus transactions from the mempool. Miners guess nonces by brute force until the block hash is below the target (starts with enough zeros). Difficulty sets the number of zeros and keeps blocks about 10 minutes apart. The block is then gossiped. It works because hashing is one-way and unpredictable, so there is no shortcut, while verification costs a single hash." },
  { id: "c-bc-consensus", topics: ["blockchain"], src: "L8 BFT & Blockchain",
    q: "What is Bitcoin's actual consensus rule, and why is PoW not 'the consensus protocol'?",
    a: "Correct nodes accept and extend the longest (most-work) chain. A new block is both a proposal and an implicit vote for the whole history it extends. There is no leader and no explicit vote. Forks happen, and the shorter branch's transactions 'didn't happen', so confirmations matter. PoW only rate-limits proposals (time to propagate) and makes votes expensive (Sybil resistance), so you cannot pretend to be many nodes. It tolerates < 1/2 Byzantine hash power." },
  { id: "c-bc-51", topics: ["blockchain"], src: "L8 BFT & Blockchain",
    q: "What can an attacker with > 50% of the hash power do?",
    a: "Out-mine everyone else: decide what goes into the longest chain, censor transactions, and rewrite history by forking from an earlier block and outgrowing the canonical chain, so 'confirmed' transactions disappear (double spend). Economic incentives (block rewards only for accepted blocks) push miners to be honest." },
  { id: "c-bc-limits", topics: ["blockchain"], src: "L8 BFT & Blockchain",
    q: "Why don't Bitcoin and Ethereum scale horizontally?",
    a: "Fixed block size and interval give fixed throughput (Bitcoin about 7 TPS realistic, Ethereum about 30 TPS with 12 s blocks). Everyone replicates the whole state and competes to add the same next block, so everyone takes part in global consensus and adding nodes does not help. Other problems: high fees, long confirmation delays and PoW energy use. Resource waste is the point of PoW." },
  { id: "c-bc-eth", topics: ["blockchain"], src: "L8 BFT & Blockchain",
    q: "Ethereum: account model, proof of stake and smart contracts.",
    a: "Accounts with balances instead of UTXOs. It switched from PoW to proof of stake: validators stake money, their chance to participate depends on the stake, and misbehaviour gets the stake slashed. Much more energy efficient, but same block interval, so the same throughput. Smart contracts are arbitrary programs run by the Ethereum Virtual Machine. Every node executes every transaction sequentially and deterministically to agree on the new state, so there is no parallel execution." },
  { id: "c-bc-scaling", topics: ["blockchain"], src: "L8 BFT & Blockchain",
    q: "How can blockchains be scaled? Layer 1 vs layer 2, and the challenges of sharding.",
    a: "Layer 1 (change the chain): bigger blocks, shorter intervals, sharding. Layer 2 (build on top): payment and state channels (Lightning, Raiden), side chains, rollups.\nSharding challenges: mapping nodes to shards, a security-performance trade-off (smaller shards are easier to take over), and cross-shard validation for dependent transactions. ScaleGraph: one chain per account, and the v nodes closest to an account (Kademlia-like distance) validate it, so disjoint transactions are validated in parallel." },

  // ------------------------------------------------------------ dht / kademlia
  { id: "c-dht-mod", topics: ["dht"], src: "L4 DHT",
    q: "Why is modulo hashing (key mod N) bad for distributing keys over nodes?",
    a: "Changing N remaps almost every key. Going from m to m+1 buckets keeps only about 1/(m+1) of the keys in place, so essentially all keys move over the network. Doubling moves half. In memory this is cheap pointer copying, but over the network it is far too expensive, and nodes join one at a time. Clients also need to know N to find a key." },
  { id: "c-dht-consistent", topics: ["dht"], src: "L4 DHT",
    q: "What is consistent hashing and how many keys move?",
    a: "Keys and nodes are hashed into the same space (e.g. a ring), and each node owns an interval, e.g. up to its ID as in Chord. A joining node splits one interval, so only about 1/(N+1) of the keys move, and a leaving node hands over about 1/N. The fraction shrinks as N grows: it is not constant. Uniform node IDs still give uneven intervals (max/mean is about log N), which virtual nodes fix." },
  { id: "c-dht-overlay", topics: ["dht"], src: "L4 DHT",
    q: "In what sense is a DHT an overlay network? What is stretch?",
    a: "A logical network on top of IP: nodes have overlay IDs, and a closeness notion defines the topology used for greedy routing and lookup. A DHT is an overlay with key-value storage added, and overlays can do other things too. Stretch is how much longer an overlay path is than the direct path in the underlying network, since overlay neighbours can be physically far apart. Other properties: lookup cost, maintenance overhead, load balance, congestion, fault tolerance, routing-table size versus hops." },
  { id: "c-dht-chord", topics: ["dht"], src: "L4 DHT",
    q: "How does Chord work?",
    a: "Node IDs and keys are on a circle mod 2^B. A key belongs to its successor, the first node clockwise. Each node keeps a finger table with shortcuts at distances 1, 2, 4, 8 and so on (like a skiplist), Θ(log N) distinct entries, giving Θ(log N) lookups. A join splits an interval and moves about 1/(N+1) of the keys. Virtual nodes (Θ(log M) per machine) balance load, and replicating on the k successors survives crashes." },
  { id: "c-dht-can", topics: ["dht"], src: "L4 DHT",
    q: "How does CAN (Content-Addressable Network) work?",
    a: "The key space is a d-dimensional torus split into zones, each with an owner. A joining node picks a point, and the zone containing it is split in half along one dimension, so about 1/(N+1) of the keys move. Each node knows Θ(d) neighbours (constant state) and routes greedily to the neighbour closest to the target in O(d·N^(1/d)) hops. Path diversity gives lower latency and resilience. Extensions: zone overloading, multiple hash functions, multiple realities." },
  { id: "c-kad-xor", topics: ["dht"], src: "L2 Kademlia / L4 DHT",
    q: "Kademlia's XOR metric: what is it and what properties does it have?",
    a: "distance(x, y) = x XOR y, read as an integer over 160-bit IDs and keys. A long common prefix gives a small distance. Properties: d(x,x) = 0, d(x,y) > 0 for x ≠ y, symmetric (so nodes learn useful contacts from the queries they receive), triangle inequality, and unidirectional (for a given x and distance there is exactly one y, so lookups for the same key converge on the same path)." },
  { id: "c-kad-buckets", topics: ["dht"], src: "L2 Kademlia / Kademlia paper",
    q: "What is a k-bucket and how is it maintained?",
    a: "Bucket i holds up to k contacts whose distance from us is in [2^i, 2^(i+1)), one bucket per ID bit, so up to 160. Each bucket is kept in least-recently-seen order. When a full bucket sees a new contact, ping the least recently seen one: if it answers, keep it and drop the newcomer, otherwise replace it. Long-lived nodes are likely to stay up, and this resists flooding attacks. The original table is a binary tree that splits the bucket covering our own ID. The lab may use a flat array of buckets." },
  { id: "c-kad-lookup", topics: ["dht"], src: "L2 Kademlia",
    q: "How does a Kademlia node lookup work?",
    a: "Take the α (usually 3) closest known contacts from the routing table and send FIND_NODE to them in parallel. They return their k closest contacts. Query the closest not-yet-queried ones, and repeat until the k closest seen have all answered and no closer node turns up. It is iterative (the initiator drives it) and takes O(log n) steps, since each step fixes at least one more prefix bit. FIND_VALUE works the same way but stops when a node returns the value." },
  { id: "c-kad-rpcs", topics: ["dht"], src: "L2 Kademlia / lab",
    q: "What are Kademlia's four RPCs?",
    a: "- PING: is the node alive?\n- STORE(key, value): store on the receiving node\n- FIND_NODE(id): return the k closest contacts you know\n- FIND_VALUE(key): return the value if stored, otherwise behave like FIND_NODE\nEvery received message also updates the receiver's buckets with the sender." },
  { id: "c-kad-join", topics: ["dht"], src: "L2 Kademlia / Kademlia paper",
    q: "How does a node join a Kademlia network, and how do tables get filled?",
    a: "It must know one bootstrap node. Insert it into the right bucket, look up your own ID (which populates the buckets near you and announces you to others), then refresh buckets further away by looking up random IDs in their ranges. After that, tables fill as a side effect of normal traffic. No O(n) scan is ever needed." },
  { id: "c-kad-store", topics: ["dht", "consistency"], src: "L5 Data sync / Kademlia paper",
    q: "How does Kademlia store values and keep them alive under churn?",
    a: "Look up the k closest nodes to the key and send STORE to them. The original publisher republishes every 24 h (the lecture uses hourly), each node holding a value re-replicates it hourly to any of the k closest that lack it, and values expire after 24 h without refresh. Results can be cached along the lookup path. The outcome is eventual consistency, which fits immutable, read-heavy data like BitTorrent peers, IPFS blocks and public keys." },

  // ------------------------------------------------------------ pubsub / messaging
  { id: "c-ps-vs-queue", topics: ["pubsub"], src: "Old lectures / exams",
    q: "Pub-sub vs message queue semantics?",
    a: "Pub-sub: a publisher sends to a topic and every subscriber gets a copy (fan-out). Messages are immutable and may be retained for replay. Message queue (point-to-point): competing consumers, where each message is delivered to exactly one receiver, spreading work, and it is removed once acknowledged. Kafka does both: across consumer groups it is pub-sub, inside one group it acts as a queue over partitions." },
  { id: "c-ps-kafka", topics: ["pubsub"], src: "Old lectures / L5 Data sync",
    q: "How is Kafka built as a distributed system?",
    a: "Topics are split into partitions (shards) spread over brokers. Each partition is an append-only, ordered, immutable log, replicated to several brokers with one leader and in-sync replicas (ISR). Consumers track offsets and can re-read within the retention window. Order is guaranteed per partition, which gives sequential consistency, not across partitions. Cluster metadata (controller, partition leaders, ISR) is agreed via ZooKeeper or KRaft (Raft), so it is not completely distributed." },
  { id: "c-ps-srm", topics: ["pubsub", "networking"], src: "Old lectures (multicast)",
    q: "How does Scalable Reliable Multicast (SRM) achieve reliability?",
    a: "With receiver-driven negative acknowledgements. A receiver that detects a gap multicasts a NACK after a random delay, and others that see it suppress their own. Any member holding the data can repair it, also after a random delay with suppression. This avoids the ACK implosion of sending an ack per packet per receiver. Badly tuned timers can still cause NACK or repair implosions." },
  { id: "c-ps-immutable", topics: ["pubsub"], src: "Old exams",
    q: "Why are pub-sub and stream systems based on immutable messages?",
    a: "Immutable messages can be replicated, cached, retransmitted, replayed and consumed by many subscribers without conflicts or coordination. Consumers just track a position. This underpins event sourcing and log-based architectures. Delivery itself can still be reliable or unreliable." },

  // ------------------------------------------------------------ big data
  { id: "c-mr-model", topics: ["bigdata", "orchestration"], src: "L8 Orchestration (2026)",
    q: "Explain the MapReduce programming model.",
    a: "The user writes two pure functions: map(k1, v1) -> list(k2, v2) and reduce(k2, list(v2)) -> list(v3). The framework splits the input, runs map in parallel, groups all intermediate values by key across machines (the shuffle, the only planned network transfer), runs reduce in parallel, and handles placement, retries and stragglers. Example: word count, map gives (word, 1) and reduce sums." },
  { id: "c-mr-cluster", topics: ["bigdata", "orchestration"], src: "L8 Orchestration (2026)",
    q: "How does MapReduce run on a cluster, and how does it handle failures?",
    a: "The master knows where each block is and places map tasks on those nodes (data locality: send kilobytes of code, not terabytes of data). Map output goes to local disk split by reducer, and reducers fetch their partitions (M × R fetches). Reduce starts only after all maps are done (a barrier). Workers heartbeat, and silence means presumed dead: running tasks and its finished map tasks are re-run, because their output died with the disk. Slow workers get backup tasks. An atomic rename commits each reduce output, so re-execution is safe because tasks are deterministic." },
  { id: "c-mr-combiner", topics: ["bigdata"], src: "Old exams",
    q: "What is a combiner in Hadoop, and when can it be used?",
    a: "A mini-reducer run on map output before the shuffle, to cut network traffic (e.g. sum the local word counts). It is only valid if the operation is commutative and associative (sum, count, max). Average is not, unless you carry (sum, count). Hadoop may run it zero or more times, so the result must not depend on it." },
  { id: "c-mr-spark", topics: ["bigdata"], src: "Old exams",
    q: "Hadoop MapReduce vs Spark?",
    a: "Hadoop MapReduce is batch processing that writes intermediate data to disk between stages, with high latency. Spark keeps datasets in memory (RDDs/DataFrames), builds a DAG of stages, is far faster for iterative jobs and machine learning, and supports streaming (micro-batches). Both run in a cluster and move computation to the data. Neither is designed for geo-distribution." },

  // ------------------------------------------------------------ security
  { id: "c-sec-pgp", topics: ["security"], src: "Old lectures",
    q: "How does PGP encrypt and sign a message? What trust model does it use?",
    a: "Hybrid encryption: generate a random symmetric session key, encrypt the payload with it (fast), and encrypt the session key with the recipient's public key. Signing: hash the message and sign the hash with the sender's private key. Trust in keys comes from a web of trust (users sign each other's keys). No CA is required." },
  { id: "c-sec-ca-tls", topics: ["security", "microservices"], src: "L11 Modern compute",
    q: "What does a CA do, and what happens in a TLS handshake?",
    a: "A certificate authority signs certificates binding a public key to an identity (domain, validity period, issuer signature). Browsers trust pre-installed root CAs. TLS: the server sends its certificate, and the client checks issuer, domain, expiry and signature. A symmetric session key is then established (in the classic version the client encrypts it with the server's public key; modern TLS uses Diffie-Hellman). In Kubernetes, cert-manager gets certificates from Let's Encrypt via ACME (HTTP-01 or DNS-01 challenge)." },
  { id: "c-sec-ipsec", topics: ["security", "networking"], src: "Old lectures",
    q: "What is IPsec used for?",
    a: "Network-layer security. AH gives authentication. ESP gives encryption and authentication. In tunnel mode whole IP packets are encapsulated between gateways, forming encrypted tunnels (site-to-site VPNs) that are transparent to applications." },

  // ------------------------------------------------------------ gaming
  { id: "c-game-arch", topics: ["gaming"], src: "L9 Gaming backends",
    q: "Peer-to-peer vs client-server vs authoritative hybrid game architectures?",
    a: "- P2P: every client sends inputs to all and runs the same deterministic simulation. No server is needed, but bandwidth grows polynomially, joining and leaving is hard, one bad link hurts everyone, and every client is trusted (easy cheating).\n- Client-server: clients send input and the server simulates and sends updates. Linear bandwidth and harder cheating, but latency is disruptive and the server carries the load.\n- Authoritative hybrid: the server decides, while clients run prediction and part of the logic. Responsive, but consistency needs care." },
  { id: "c-game-lockstep", topics: ["gaming"], src: "L9 Gaming backends",
    q: "What is deterministic lockstep?",
    a: "All players start from the same state and send only their inputs for frame n. Everyone waits until all inputs for frame n have arrived, then simulates frame n identically. Low bandwidth and full consistency, but it requires a perfectly deterministic simulation, waits for the slowest player, and late joining is impossible. Used in RTS games (StarCraft), and in fighting games with rollback." },
  { id: "c-game-snapshot", topics: ["gaming"], src: "L9 Gaming backends",
    q: "What is snapshot interpolation?",
    a: "The server periodically sends timestamped snapshots of the state. The client buffers them and renders slightly in the past, interpolating between the two snapshots around the render time. It looks smooth even at low tick rates and needs no waiting for inputs, but uses more bandwidth and adds delay. Used in shooters and MOBAs. Delta compression sends only changes, but needs reliable delivery or compensation." },
  { id: "c-game-lagcomp", topics: ["gaming"], src: "L9 Gaming backends",
    q: "Client-side prediction, server reconciliation and server-side rewind: what are they?",
    a: "- Client-side prediction: apply your own input locally at once instead of waiting a round trip.\n- Server reconciliation: when the authoritative state arrives, correct the client (snap, linear or higher-order blending) and replay unacknowledged inputs.\n- Server-side rewind (lag compensation): estimate the shooter's latency, rewind other players to where the shooter saw them, evaluate the shot, then restore. The acting player gets the advantage." },
  { id: "c-game-dr", topics: ["gaming"], src: "L9 Gaming backends",
    q: "What is dead reckoning?",
    a: "Predict an entity's position from its last known state: s(t) = s0 + v0·t + ½·a·t². The owner only sends an update when the true position deviates from the prediction by more than a threshold. It hides latency and saves bandwidth at the cost of temporary inconsistencies. Used in FPS, racing and simulations." },
  { id: "c-game-udp", topics: ["gaming", "networking"], src: "L9 Gaming backends",
    q: "Why do most real-time games use UDP rather than TCP?",
    a: "Only the newest state matters. TCP's in-order retransmission causes head-of-line blocking and latency spikes, Nagle's algorithm adds delay, and you get less control. With UDP, a lost update is simply replaced by the next (idempotent state updates), and the game adds its own sequence numbers, selective reliability, compression and aggregation." },
  { id: "c-game-scale", topics: ["gaming"], src: "L9 Gaming backends",
    q: "How are large online games (MMOs) scaled?",
    a: "Partition the world into areas, each run by a game server. A world server tracks where players are, directs them to the right area server and hands over when they cross borders (adjacent areas get broadcasts of nearby objects, e.g. via pub-sub). Clients only receive relevant updates (area of interest). When one area is overcrowded, WoW-style 'sharding' (layering) creates copies of the zone and players only see others on their copy. Alternatively distribute clients over servers that exchange state, which costs more inter-server traffic." },
  { id: "c-game-tick", topics: ["gaming"], src: "L9 Gaming backends",
    q: "What is tick rate and how does it differ between genres?",
    a: "The number of server game-loop updates per second (60 Hz is about 16.7 ms per tick). A higher tick rate gives lower input latency and better hit detection, at higher server load, bandwidth and cost. FPS 60-128 Hz (server-authoritative hybrid), MOBA 30-60 Hz, RTS 10-30 Hz (lockstep), MMORPG 10-20 Hz (eventual consistency), turn-based none (full consistency), fighting games use frame-based lockstep with rollback." },
  { id: "c-game-cheat", topics: ["gaming", "security"], src: "L9 Gaming backends",
    q: "How do game backends defend against cheating?",
    a: "Never trust client data: sanity-check every value, keep the server authoritative, encrypt packets and add checksums, use sequence numbers against replay attacks, add random data to encrypted packets, monitor for irregular progress, and as a last resort use kernel (ring-0) anti-cheat. Security through obscurity eventually fails." },

  // ------------------------------------------------------------ microservices
  { id: "c-ms-def", topics: ["microservices"], src: "L11 Modern compute",
    q: "What is a microservice architecture?",
    a: "One application built as a suite of small services, each in its own process, communicating via lightweight mechanisms (REST, gRPC, messaging) and independently deployable by automated pipelines.\n- Teams own a service from development to operations\n- Each service picks its own language and has its own data store (no shared database)\n- Designed for partial failure (resilience)\n- CI/CD and monitoring for fast delivery" },
  { id: "c-ms-soa", topics: ["microservices"], src: "L11 Modern compute",
    q: "SOA vs microservices: what went wrong with SOA?",
    a: "SOA had services with well-defined interfaces (loose coupling, reuse, discoverability) but in practice relied on an Enterprise Service Bus, which became a bottleneck and a single point of failure. It used verbose XML/SOAP/WSDL, stateful EJBs tied to app servers (hard to scale) and big centralised integration projects. Microservices use dumb pipes with smart endpoints, lightweight protocols, containers and decentralised ownership." },
  { id: "c-ms-mesh", topics: ["microservices"], src: "L11 Modern compute",
    q: "What is a service mesh?",
    a: "An infrastructure layer for service-to-service traffic. A sidecar proxy next to each service plus a central control plane (Istio, Linkerd, Consul Connect) provide mTLS (zero trust), traffic shaping (canary, blue/green), retries, circuit breaking and fail-over, observability (metrics, traces) and policies on who may talk to whom, all without changing application code." },
  { id: "c-ms-breaker", topics: ["microservices"], src: "L11 Modern compute",
    q: "What is a circuit breaker?",
    a: "After repeated failures to a backend, it 'opens' and fails fast with an immediate error instead of waiting for timeouts. This prevents cascading failures as callers stop piling up. After a while it half-opens to probe whether the backend has recovered. Doing it in a shared mesh sidecar gives consistent behaviour across hundreds of services." },
  { id: "c-ms-discovery", topics: ["microservices"], src: "L11 Modern compute",
    q: "How do microservices find each other?",
    a: "Through a service registry: Consul, Eureka, etcd or ZooKeeper, with health checks. Kubernetes gives each Service a stable virtual ClusterIP plus a DNS name (CoreDNS), and kube-proxy (iptables/IPVS) or eBPF load-balances to the pod endpoints selected by labels. DNS-based discovery is simple but limited by caching and TTL." },
  { id: "c-ms-containers", topics: ["microservices", "orchestration"], src: "L10/L11",
    q: "Containers vs virtual machines?",
    a: "A VM runs a full guest OS on a hypervisor: strong isolation, heavier, slow to start. A container packages an application and its dependencies but shares the host kernel (namespaces and cgroups): lightweight, starts almost instantly, so it suits elastic scaling. The cost is weaker isolation (container escape affects the host and others, and compromised images spread)." },
  { id: "c-ms-serverless", topics: ["microservices", "orchestration"], src: "L11 Modern compute",
    q: "What is serverless / Function-as-a-Service, and what are its trade-offs?",
    a: "You deploy individual functions. The provider runs and scales them (0 to thousands of instances), triggered by events (HTTP, queues, schedules), and you pay per millisecond of execution. Functions must be stateless and idempotent, with state in managed services. Examples: AWS Lambda, Azure and Google Cloud Functions, Knative and OpenFaaS on Kubernetes. Trade-offs: cold starts, execution limits, vendor lock-in, harder debugging." },

  // ------------------------------------------------------------ orchestration
  { id: "c-orch-defs", topics: ["orchestration"], src: "L8 Orchestration (2026)",
    q: "Workflow vs scheduling vs orchestration?",
    a: "- Workflow: the specification. A DAG of tasks and dependencies plus what each consumes and produces. It says what and in which order, not where or when.\n- Scheduling: the decision. Which READY task runs on which machine, when, ahead of whom, made online by a policy.\n- Orchestration: the control loop. Track readiness, schedule, dispatch, execute, record outcomes, recover from failure and expose state, repeated until all tasks are done." },
  { id: "c-orch-dag", topics: ["orchestration"], src: "L8 Orchestration (2026)",
    q: "When is a DAG task READY? What are work and span, and what bound do they give?",
    a: "A task is ready when every parent's recorded state (the coordinator's record, not a machine's belief) is SUCCESS. States: WAITING, READY, RUNNING, SUCCESS or FAILED, with retries while the budget allows. Work T1 is the sum of all task times. Span T∞ is the longest (critical) path. Makespan on m machines is at least max(T1/m, T∞). When the span dominates, more machines cannot help." },
  { id: "c-orch-graham", topics: ["orchestration"], src: "L8 Orchestration (2026)",
    q: "What is Graham's anomaly, and how does critical-path-first fix it?",
    a: "With greedy list scheduling and a fixed priority list, adding a machine can make the schedule longer. In the lecture example, 3 machines finish in 12 but 4 machines take 15, because short tasks become ready early and grab the machine the critical-path task needed. Fix: rank each task by its own time plus the longest path through its successors and always start the highest rank first. That gives makespan 12, equal to the span, on 4 machines." },
  { id: "c-orch-binpack", topics: ["orchestration"], src: "L8 Orchestration (2026)",
    q: "Why is placement bin packing, and how do schedulers handle that it is NP-hard?",
    a: "Fit demand vectors (CPU, memory, GPU) into capacity vectors using few machines. A proposed placement is easy to check (one sum per server) but hard to find: brute force tries k^n assignments, which is NP-complete via a reduction from PARTITION. Schedulers use heuristics: first-fit, best-fit, first-fit decreasing (buffer, sort large-first, then first-fit; reached the optimal 4 servers in the lecture example where FF used 6 and BF 5), or meta-heuristics such as genetic algorithms. Policy choice: pack (fewest machines, failures concentrate) or spread (survives machine loss, wastes capacity)." },
  { id: "c-orch-ga", topics: ["orchestration"], src: "L8 Orchestration (2026)",
    q: "How does a genetic algorithm solve a placement problem?",
    a: "A chromosome is a placement written as a string (gene i = server of allocation i). Fitness is the over-allocation score, where 0 means it fits. Loop:\n- Evaluate: decode and score\n- Select: keep the fit (best half, roulette or tournament)\n- Crossover: cut two parents at the same point and swap tails\n- Mutate: rarely flip a gene, so moves no parent contains can happen\n- Next generation\nStop when the score stops improving or the budget runs out. It only needs a string representation and a score." },
  { id: "c-orch-little", topics: ["orchestration"], src: "L8 Orchestration (2026)",
    q: "State Little's law and the utilisation lesson.",
    a: "L = λ·W: average number in the system equals arrival rate times average time in the system. It holds for any stable system (arrivals below capacity) with any arrival pattern, order or number of servers. For M/M/2 the queue wait is W_q = ρ²·τ/(1−ρ²), which explodes as utilisation ρ approaches 1. With τ = 4 min it is about 9 min at 83%, 17 min at 90% and 30 min at 94%. Running servers near 100% busy means very long queues." },
  { id: "c-orch-backfill", topics: ["orchestration"], src: "L8 Orchestration (2026)",
    q: "What is backfilling in batch schedulers?",
    a: "The head-of-queue job gets a reservation for the earliest time enough nodes are free. Later, smaller jobs may start now on idle nodes if they finish before that reservation, so they do not delay the head job. Machines stay busy without starving large jobs. It needs runtime estimates. Related policies: priority decay (fair share) and carbon-aware scheduling (run when grid carbon intensity is low)." },
  { id: "c-k8s-arch", topics: ["orchestration"], src: "L11 Modern compute / L8 Orchestration",
    q: "What are the main Kubernetes components, and what happens from 'kubectl apply' to a running pod?",
    a: "Control plane: kube-apiserver (the only door to the record), etcd (the cluster state, replicated with Raft), controller manager, kube-scheduler. Workers: kubelet, kube-proxy, container runtime, CNI network plugin.\nFlow: apply a Deployment, the API server writes it to etcd, controllers create ReplicaSet and Pod objects with no node yet, the scheduler filters (resources, taints, affinity), scores (least allocated, image locality, spread) and binds a node, then that node's kubelet pulls images, starts containers with cgroup limits and reports status." },
  { id: "c-k8s-declarative", topics: ["orchestration"], src: "L11 Modern compute",
    q: "What does it mean that Kubernetes is declarative, and what is a controller?",
    a: "You state the desired state ('3 replicas of this image'), not the steps. Controllers are reconciliation loops: observe the actual state via the API server, compare it with the spec, act to close the gap (e.g. start a missing pod), and repeat forever. Examples: ReplicaSet, Deployment (rolling updates), Job, Node (marks NotReady and evicts), Ingress, HorizontalPodAutoscaler. Operators are custom controllers for custom resource types (CRDs)." },
  { id: "c-k8s-objects", topics: ["orchestration"], src: "L11 Modern compute",
    q: "Pod, Deployment, StatefulSet, Service, Ingress: what is each?",
    a: "- Pod: the smallest deployable unit, one or more tightly coupled containers sharing an IP and volumes\n- Deployment: stateless, interchangeable replicas with rolling updates\n- StatefulSet: stable identities, persistent volumes (PVCs) and ordered start-up, for databases and queues\n- Service: a stable ClusterIP and DNS name that load-balances to pods selected by labels\n- Ingress: HTTP(S) routing from outside by host and path, with TLS termination by the ingress controller (Traefik, NGINX)" },
  { id: "c-k8s-tradeoff", topics: ["orchestration"], src: "L11 Modern compute",
    q: "What is the trade-off of Kubernetes?",
    a: "You get self-healing, scaling, load balancing, service discovery and immutable, declarative infrastructure. You pay with complexity: a steep learning curve, YAML sprawl, too many ecosystem choices, hard debugging, painful upgrades and multi-cluster management, security pitfalls (shared kernel, image vulnerabilities, RBAC, secrets), and over-engineering where a simple solution would do." },
  { id: "c-orch-pull", topics: ["orchestration"], src: "L8 Orchestration (2026)",
    q: "Why do cross-site orchestrators like ColonyOS use a broker that executors pull work from?",
    a: "Edge and HPC sites sit behind NAT and firewalls owned by others. Inbound calls are blocked, but outbound connections work almost everywhere. A reachable broker (rendezvous) holds the queue and the durable record, and executors connect outward and ask for work when they have capacity. Pull gives back-pressure (no work pushed to overloaded nodes), and a lost pull request is simply asked again. The cost is that the broker is a single point of failure, so it is made durable or replicated." },
  { id: "c-orch-lease", topics: ["orchestration", "consistency"], src: "L8 Orchestration (2026)",
    q: "How do leases, atomic claims and idempotent completion protect against failures in orchestration?",
    a: "A dead machine looks exactly like a slow one, so every assignment has a deadline (a lease, e.g. maxexectime). When it expires the task is re-placed. Because the first copy may still be alive (partition), you need:\n- an atomic claim (one conditional DB update, WAITING to RUNNING, one winner)\n- idempotent completion (a close is accepted once per attempt, and a late close from an old attempt is refused)\n- reconciliation before retrying external side effects (e.g. check whether the Slurm job still exists before running sbatch again)\nControl state must live in a durable record that outlives any machine." },
  { id: "c-orch-straggler", topics: ["orchestration", "bigdata"], src: "L8 Orchestration (2026)",
    q: "How do you handle stragglers and infeasible placements?",
    a: "Straggler: one slow parallel task delays the whole workflow. Use speculative execution: start a backup copy elsewhere, take the first result and cancel the other. This requires idempotent tasks and a record that accepts one result (MapReduce backup tasks). Infeasible placement (e.g. a GPU task on a CPU node): match before assigning, so the task states conditions, the executor states capabilities, and only feasible pairs are matched." },
  { id: "c-orch-data", topics: ["orchestration", "bigdata"], src: "L8 Orchestration (2026)",
    q: "Passing data by value vs by reference between workflow steps?",
    a: "By value: the message carries the bytes (RPC arguments, small results; kilobytes). By reference: the message carries a name (e.g. s3://lab/D7-clean v1) and the bytes are fetched where the consumer runs. Placement decides how much data must move, so put computation near the data. References should include a version or hash, checked before use, so a truncated or stale file fails fast." }
];
